class Mat {
 public:
 int rows=0,cols=0,type=0;std::vector<Vec3b> pixels;float* floats=nullptr;
 Mat()=default;
 Mat(int h,int w,int t,void* ptr):rows(h),cols(w),type(t),pixels(size_t(h)*w),floats(static_cast<float*>(ptr)){}
